import{_ as a,o as t,c as o,a0 as i}from"./chunks/framework.DYS8d9tm.js";const p=JSON.parse('{"title":"📋 Sovereign Deployment Checklist","description":"","frontmatter":{},"headers":[],"relativePath":"deployment/deployment_checklist.md","filePath":"deployment/deployment_checklist.md"}'),r={name:"deployment/deployment_checklist.md"};function l(n,e,c,s,d,h){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="📋-sovereign-deployment-checklist" tabindex="-1">📋 Sovereign Deployment Checklist <a class="header-anchor" href="#📋-sovereign-deployment-checklist" aria-label="Permalink to &quot;📋 Sovereign Deployment Checklist&quot;">​</a></h1><p>Use this checklist to ensure your WealthFam instance is properly orchestrated for privacy-first financial engineering.</p><h2 id="pre-deployment" tabindex="-1">Pre-Deployment <a class="header-anchor" href="#pre-deployment" aria-label="Permalink to &quot;Pre-Deployment&quot;">​</a></h2><h3 id="repository-setup" tabindex="-1">Repository Setup <a class="header-anchor" href="#repository-setup" aria-label="Permalink to &quot;Repository Setup&quot;">​</a></h3><ul><li>[ ] Required repositories are cloned locally (Infra, Backend, Parser, Frontend).</li><li>[ ] Infrastructure blueprints are ready in <code>Infra/docker</code>.</li><li>[ ] <code>.env</code> is configured with a secure <code>SECRET_KEY</code>.</li></ul><h3 id="docker-environment" tabindex="-1">Docker Environment <a class="header-anchor" href="#docker-environment" aria-label="Permalink to &quot;Docker Environment&quot;">​</a></h3><ul><li>[ ] Docker and Docker Compose installed (v2.0+ recommended).</li><li>[ ] Sufficient disk space for database volumes (PostgreSQL and DuckDB; 1GB+ recommended for start).</li><li>[ ] Port <code>80</code> (or your chosen internal port) is available.</li></ul><hr><h2 id="deployment-stages" tabindex="-1">Deployment Stages <a class="header-anchor" href="#deployment-stages" aria-label="Permalink to &quot;Deployment Stages&quot;">​</a></h2><h3 id="stage-1-local-orchestration-docker" tabindex="-1">Stage 1: Local Orchestration (Docker) <a class="header-anchor" href="#stage-1-local-orchestration-docker" aria-label="Permalink to &quot;Stage 1: Local Orchestration (Docker)&quot;">​</a></h3><ul><li>[ ] <code>docker-compose up -d</code> executed from <code>Infra/docker</code>.</li><li>[ ] All 3 core services (Backend, Parser, Frontend) are <code>running</code>.</li><li>[ ] Health endpoint responds: <code>curl http://localhost/health</code>.</li><li>[ ] Database files/containers are active and schema migrations have succeeded.</li></ul><h3 id="stage-2-mobile-connectivity" tabindex="-1">Stage 2: Mobile Connectivity <a class="header-anchor" href="#stage-2-mobile-connectivity" aria-label="Permalink to &quot;Stage 2: Mobile Connectivity&quot;">​</a></h3><ul><li>[ ] Latest APK installed on Android device.</li><li>[ ] Server URL set to local IP (e.g., <code>http://192.168.1.100</code>).</li><li>[ ] SMS permissions granted.</li><li>[ ] Device authorized in <strong>Web UI → Settings → Devices</strong>.</li></ul><hr><h2 id="post-deployment-verification" tabindex="-1">Post-Deployment Verification <a class="header-anchor" href="#post-deployment-verification" aria-label="Permalink to &quot;Post-Deployment Verification&quot;">​</a></h2><h3 id="precision-integrity" tabindex="-1">Precision Integrity <a class="header-anchor" href="#precision-integrity" aria-label="Permalink to &quot;Precision Integrity&quot;">​</a></h3><ul><li>[ ] Can register the primary Family Owner account.</li><li>[ ] Transaction Triage queue loads correctly.</li><li>[ ] AI Insights generate (if <code>GEMINI_API_KEY</code> is set).</li></ul><h3 id="security-privacy" tabindex="-1">Security &amp; Privacy <a class="header-anchor" href="#security-privacy" aria-label="Permalink to &quot;Security &amp; Privacy&quot;">​</a></h3><ul><li>[ ] <strong>Masking Mode</strong> verified (Eye icon obfuscates values).</li><li>[ ] Background SMS service shows persistent notification.</li><li>[ ] No external traffic except to authorized endpoints (Gemini, IMAP).</li></ul><hr><h2 id="maintenance" tabindex="-1">Maintenance <a class="header-anchor" href="#maintenance" aria-label="Permalink to &quot;Maintenance&quot;">​</a></h2><h3 id="backup-strategy" tabindex="-1">Backup Strategy <a class="header-anchor" href="#backup-strategy" aria-label="Permalink to &quot;Backup Strategy&quot;">​</a></h3><ul><li>[ ] Automated backup script for PostgreSQL database dump, persistent <code>/data/vault</code> (Document Vault &amp; statement PDFs), <code>ingestion_engine_parser.duckdb</code>, and <code>telemetry.duckdb</code> scheduled.</li><li>[ ] Off-site backup (e.g., Encrypted Cloud Storage or NAS) verified.</li></ul><h3 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h3><ul><li>[ ] <code>git pull</code> on Infra repo for latest orchestration logic.</li><li>[ ] <code>docker-compose pull</code> to fetch latest microservice images.</li><li>[ ] <code>docker-compose up -d</code> to apply updates with zero downtime objective.</li></ul><hr><h2 id="🆘-troubleshooting" tabindex="-1">🆘 Troubleshooting <a class="header-anchor" href="#🆘-troubleshooting" aria-label="Permalink to &quot;🆘 Troubleshooting&quot;">​</a></h2><ul><li>[ ] Check logs: <code>docker-compose logs -f</code>.</li><li>[ ] Verify database permissions: <code>ls -la ./data</code>.</li><li>[ ] Refer to the <a href="./deployment.html">Full Deployment Guide</a>.</li><li>[ ] Join the <a href="https://discord.gg/wealthfam" target="_blank" rel="noreferrer">Discord Community</a>.</li></ul><hr><div align="center"> *Engineering Financial Freedom* *Made with ❤️ by WGLabz* </div>',30)])])}const m=a(r,[["render",l]]);export{p as __pageData,m as default};
